  active?: boolean;
}) {
  return (
    <button
      title={title}
      onClick={onClick}
      className={cn(
        "grid h-7 w-7 place-items-center rounded-md text-ink-muted hover:bg-[var(--color-surface-2)] hover:text-foreground transition-colors",
