                  {s.output.kind === "abstract" && <AbstractCard />}
                  {s.output.kind === "publish" && <PublishCard />}
                  {s.output.kind === "conferences" && <ConferencesCard />}
                  {s.output.kind === "memory" && <MemoryCard />}
                </div>
