    21	// h3 swallows in-handler throws into a normal 500 Response with body
    22	// {"unhandled":true,"message":"HTTPError"} — try/catch alone never fires for those.
    23	async function normalizeCatastrophicSsrResponse(response: Response): Promise<Response> {
    24	  if (response.status < 500) return response;
    25	  const contentType = response.headers.get("content-type") ?? "";
    26	  if (!contentType.includes("application/json")) return response;
    27	
    28	  const body = await response.clone().text();
    29	  if (!body.includes('"unhandled":true') || !body.includes('"message":"HTTPError"')) {
    30	    return response;
    31	  }
    32	
    33	  console.error(consumeLastCapturedError() ?? new Error(`h3 swallowed SSR error: ${body}`));
    34	  return new Response(renderErrorPage(), {
