        </div>
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-0 border-b border-border bg-[var(--color-sidebar)] px-3">
        {(["Paper", "PDF Preview", "LaTeX"] as Tab[]).map((t) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className={cn(
