+  const regex = /(\\[a-zA-Z]+|\{[^{}]*\}|%[^\n]*)/g;
+  let last = 0;
+  let match: RegExpExecArray | null;
+  let key = 0;
+
+  while ((match = regex.exec(line))) {
+    if (match.index > last) parts.push(line.slice(last, match.index));
+    const token = match[0];
+    if (token.startsWith("\\")) {
+      parts.push(
+        <span key={key++} style={{ color: "#9db8d4" }}>
+          {token}
+        </span>,
+      );
